import subprocess,re,sys,os
files=subprocess.run(['git','diff','--name-only','c1ce2a35e1','7858d0e97b','--','ProjectFortress/src','Library','ProjectFortress/LibraryBuiltin','Specification'],capture_output=True,text=True).stdout.split()
def hunks(f):
    out=subprocess.run(['git','diff','-U0','c1ce2a35e1','7858d0e97b','--',f],capture_output=True,text=True).stdout
    hs=[]
    for m in re.finditer(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@',out,re.M):
        hs.append((int(m.group(1)),int(m.group(2) or 1),int(m.group(3)),int(m.group(4) or 1)))
    return hs
def mp(hs,line):
    off=0
    for a,al,b,bl in hs:
        if al==0:
            if line>a: off=(b+bl-1)-a
            continue
        end=a+al-1
        if line>end: off=(b+bl-1)-end
        elif line>=a: return None
    return line+off
for rec in sys.argv[1:]:
    # entries as they stood at the base, to see which citations were written against base lines
    txt=open(rec).read()
    base=subprocess.run(['git','show','c1ce2a35e1:'+rec],capture_output=True,text=True).stdout
    baselines={}
    for l in base.split('\n'):
        m=re.match(r'- ([FP]-\d+) ',l)
        if m: baselines[m.group(1)]=l
    tot=0
    for l in txt.split('\n'):
        m=re.match(r'- ([FP]-\d+) ',l)
        if not m: continue
        e=m.group(1)
        if baselines.get(e)!=l: continue   # entry rewritten in this batch: its lines are main's
        for f in files:
            bn=os.path.basename(f)
            if bn.endswith('.pdf'): continue
            hs=None
            for c in re.finditer(re.escape(bn)+r'((?:`?,? ?`?:\d+(?:-\d+)?)+)',l):
                if hs is None: hs=hunks(f)
                for n in re.finditer(r':(\d+)(?:-(\d+))?',c.group(1)):
                    a=int(n.group(1)); na=mp(hs,a)
                    if na!=a:
                        tot+=1; print(rec.split('/')[-1],e,bn,':'+n.group(0)[1:],'->',('edited' if na is None else na))
    print(rec,'moved or edited citations:',tot)
